using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows.Forms;using System.Drawing;
namespace CFEditor {
sealed partial class EditorForm {
 internal void WaitPreviewIdle(){var clock=System.Diagnostics.Stopwatch.StartNew();while(initializing||busy){Application.DoEvents();System.Threading.Thread.Sleep(1);if(clock.ElapsedMilliseconds>10000)throw new TimeoutException("Preview initialization did not settle");}}
 static void TestNeed(bool ok,string message){if(!ok)throw new InvalidOperationException(message);}
 IEnumerable<Control> AllChildren(Control root){foreach(Control c in root.Controls){yield return c;foreach(var nested in AllChildren(c))yield return nested;}}
 public async Task<List<string>> VerifyPreview(string folder){
  TestNeed(preview,"UI tests require preview");StartPosition=FormStartPosition.Manual;Location=new Point(-12000,-12000);ShowInTaskbar=false;Show();WaitPreviewIdle();Application.DoEvents();await RefreshDevice();var result=new List<string>();
  var mock=(PreviewBackend)backend;TestNeed(mock.Writes.Count==0,"Opening and reading UI wrote parameters");result.Add("Startup and refresh: no writes");
  TestNeed(selectors.Values.All(c=>c.Enabled),"A read model selector is disabled");result.Add("Amp and both FX model selectors remain enabled after reading their active assets");
  var boost=AllChildren(strips["amp"]).OfType<Knob>().Single(k=>k.Binding.Param.id=="Boost");var toggle=AllChildren(strips["amp"]).OfType<ActionButton>().Single(b=>b.Text=="OFF"||b.Text=="ON");var enable=new Binding("CatalystGroupAmp",catalog.Find("Chime").parameters.Single(p=>p.id=="BoostEnable"));
  await mock.Set(enable,0);TestNeed(!boost.Enabled&&toggle.Enabled&&toggle.Text=="OFF","Boost off appearance or switch access");int gain=boost.Value;await mock.Set(enable,1);TestNeed(boost.Enabled&&toggle.Text=="ON"&&boost.Value==gain,"Boost on changes amount");result.Add("Boost OFF grays dial; ON/OFF remains enabled below it; amount preserved");
  var preampType=new Binding("CFPreamp",Catalog.Int("type","Tipo",0,3));var tone=AllChildren(strips["amp"]).OfType<Knob>().Single(k=>k.Binding.Group=="CFPreamp"&&k.Binding.Param.id=="tone");var pedalLevel=AllChildren(strips["amp"]).OfType<Knob>().Single(k=>k.Binding.Group=="CFPreamp"&&k.Binding.Param.id=="level");await mock.Set(preampType,0);TestNeed(!tone.Enabled&&pedalLevel.Enabled,"Transparent Boost claims an unused Tone or disables Level");await mock.Set(preampType,3);TestNeed(tone.Enabled&&pedalLevel.Enabled,"SD-1 tone did not recover on type change");result.Add("Transparent Boost exposes its real Level and grays its unused Tone; switching to SD-1 restores Tone without refreshing the whole device");
  foreach(string group in new[]{"CatalystGroupEffect","CatalystGroupReverb"}){var header=strips[group].Parent;var pre=AllChildren(header).OfType<ActionButton>().Single(b=>b.Text=="PRE");var post=AllChildren(header).OfType<ActionButton>().Single(b=>b.Text=="POST");TestNeed(pre.Accent==EditorColors.Group(group)&&post.Accent==pre.Accent,"FX colors");var setting=new Binding(group,Catalog.Int("graphSlot_PostState","Position",0,1));await mock.Set(setting,1);TestNeed(post.Active&&!pre.Active,"POST selection");await mock.Set(setting,0);TestNeed(pre.Active&&!post.Active,"PRE selection");}result.Add("Both FX: separate PRE and POST, exclusive state, correct green/orange colors");
  var counts=new Dictionary<string,int>();for(int pass=0;pass<2;pass++)foreach(var asset in catalog.Effects){await mock.SelectAsset("CatalystGroupEffect",asset.id);await RefreshDevice();TestNeed(readers.Values.Sum(list=>list.Count)==bindings.Count,"Orphan readers after FX change");if(pass==0)counts[asset.id]=bindings.Count;else TestNeed(counts[asset.id]==bindings.Count,"Bindings leaked after repeated model change");}result.Add("All 24 FX switched twice: no subscription or stale control leaks");
  foreach(var asset in catalog.Amps){await mock.SelectAsset("CatalystGroupAmp",asset.id);await RefreshDevice();TestNeed(readers.Values.Sum(list=>list.Count)==bindings.Count,"Amp binding lifecycle");}result.Add("All 12 amps rebuild available parameters without duplicate readers");
  await mock.SelectAsset("CatalystGroupAmp","Chime");await mock.SelectAsset("CatalystGroupEffect","VintageDigital");await mock.SelectAsset("CatalystGroupReverb","VintageDigital");await RefreshDevice();ArrangeSound();Application.DoEvents();ArrangeSound();Application.DoEvents();
  TestNeed(!((Panel)pages[0]).VerticalScroll.Visible&&!((Panel)pages[0]).HorizontalScroll.Visible,"Main page requires scrolling");foreach(string name in new[]{"amp","advancedAmp","gate","CatalystGroupEffect","CatalystGroupReverb"}){var strip=strips[name];foreach(Control control in strip.Controls)TestNeed(control.Right<=strip.ClientSize.Width&&control.Bottom<=strip.ClientSize.Height,"Clipped control: "+name+" "+control.Bounds+" in "+strip.ClientSize);}result.Add("Largest FX layout: full-size dials fit without main-page scroll or clipping");
  Snapshot(Path.Combine(folder,"largest-fx.png"),0);
  await mock.SelectAsset("CatalystGroupEffect","SimpleDelay");await mock.SelectAsset("CatalystGroupReverb","Ganymede");await RefreshDevice();ArrangeSound();Application.DoEvents();Snapshot(Path.Combine(folder,"boost-on.png"),0);
  foreach(var pair in strips){var strip=pair.Value;foreach(Control header in strip.Parent.Controls)if(header.Name=="CardHeader")TestNeed(!header.Bounds.IntersectsWith(strip.Bounds),"Header covers dials: "+pair.Key+" "+header.Bounds+" / "+strip.Bounds);}result.Add("Fixed-height amp and FX headers never cover the dial strips");
  RefreshAdvanced();TestNeed(advancedBindings.Values.All(b=>b.Editable),"Readonly data editable in advanced table");result.Add("Advanced excludes state-only values");
  TestNeed(!AllChildren(pages[0]).OfType<Label>().Any(l=>l.Text=="El IR incorpora su micro de captura."),"Removed helper text still visible");result.Add("Requested helper text removed; NAM caption has separate source-aware label");
  ShowPage(5);WaitPreviewIdle();Application.DoEvents();Control host=InitialCFResources.UnifiedWorkspace?(Control)firmware.DataView:firmware.Child;TestNeed(firmware.Created&&host.Parent==pages[4],"Firmware workspace is not embedded");TestNeed(host.Width==pages[4].ClientSize.Width&&host.Top==0&&host.Height==(InitialCFResources.UnifiedWorkspace?pages[4].ClientSize.Height:Math.Min(pages[4].ClientSize.Height,552)),"Firmware workspace does not fill tab below mode selector");TestNeed(FirmwareCodec.Hash(FirmwareTab.Payload())==FirmwareTab.InstallerHash,"Embedded component changed");TestNeed(!AppDomain.CurrentDomain.GetAssemblies().Any(a=>a.GetName().Name=="EngineCLIWrapper"),"Preview loaded the USB SDK");firmware.PreviewDataMode(true);firmware.PreviewClickTab(3);Snapshot(Path.Combine(folder,"firmware-nam.png"),5);result.Add("Integrated firmware workspace fills the tab; pinned component unchanged; NAM tab usable; no USB SDK loaded");
  MinimumSize=new Size(1280,878);ClientSize=new Size(1440,840);for(int i=0;i<(InitialCFResources.UnifiedWorkspace?5:4);i++){firmware.PreviewClickTab(i);Application.DoEvents();Snapshot(Path.Combine(folder,i<3?"firmware-ir"+(i+1)+".png":"firmware-nam"+(i-2)+".png"),5);}result.Add("Actual button clicks switch all firmware slots in preview while installation stays disabled");
  firmware.PreviewDataMode(true);Application.DoEvents();TestNeed(firmware.DataMode&&firmware.DataView.Visible&&!firmware.DataView.InitialMode&&(InitialCFResources.UnifiedWorkspace?firmware.Child==null:!firmware.Child.Visible),"Firmware data mode visibility");
  for(int i=0;i<5;i++){((IButtonControl)firmware.DataView.Tab(i)).PerformClick();TestNeed(firmware.DataView.SelectedSlot==i&&!firmware.DataView.SendEnabled,"Data tab selection or unverified send");}
  TestNeed(!AppDomain.CurrentDomain.GetAssemblies().Any(a=>a.GetName().Name=="EngineCLIWrapper"),"Data workspace loaded the SDK");
  foreach(Control control in AllChildren(firmware.DataView).Where(c=>c.Visible))TestNeed(control.Left>=0&&control.Top>=0&&control.Right<=control.Parent.ClientSize.Width&&control.Bottom<=control.Parent.ClientSize.Height,"Clipped data workspace: "+control.Text);
  await ChangePage(4);Application.DoEvents();TestNeed(!firmware.DataMode&&(InitialCFResources.UnifiedWorkspace?firmware.DataView.Visible&&firmware.DataView.InitialMode&&firmware.Child==null:firmware.Child.Visible&&!firmware.DataView.Visible),"Installation mode not restored");result.Add("Initial installer restored with one action; data mode has five selectable slots without SDK or unverified send");
  MinimumSize=new Size(1280,878);ClientSize=new Size(1440,840);for(int page=0;page<nav.Count;page++){ShowPage(page);WaitPreviewIdle();Application.DoEvents();if(page==0)ArrangeSound();Snapshot(Path.Combine(folder,"page-"+page+".png"),page);foreach(Control c in AllChildren(pages[PageSurface(page)]).Where(c=>c.Visible&&(c is ActionButton||c is ComboBox||c is CheckBox))){var parent=c.Parent;TestNeed(c.Left>=0&&c.Top>=0&&c.Right<=parent.ClientSize.Width&&c.Bottom<=parent.ClientSize.Height,"Clipped interactive control on page "+page+": "+c.Text+" "+c.Bounds+" inside "+parent.ClientSize);}}result.Add("All six main views: interactive controls fit their parent panels");
  PaintContractTests.Verify(firmware.Assembly,folder);result.Add("Translated partial paints: buttons, labels, checkboxes, dials and numeric text stay inside their clip; zero stray pixels");
  VerifyDiagonalLayout();result.Add("Corner resize only: proportional bounds, stable FX rows, no parameter writes; preview header button hidden");
  AuditTypography(folder);result.Add("All six main views: readable type sizes, label line heights, uniform navigation and clean text encoding");
  ShowPage(0);Application.DoEvents();TestNeed(!firmware.Active,"Firmware polling not stopped when leaving tab");result.Add("Leaving Firmware CF deactivates its polling");return result;
 }
}
}
